package com.chain.contracts;

import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.Map;
import java.util.HashMap;
import java.nio.ByteBuffer;

/**
 * Smart contract for cross-chain asset bridge
 * Deployed as a sidecar in Kubernetes pod alongside validator node
 */
public class AssetBridgeContract {

    private final ConcurrentHashMap<String, TransferState> pendingTransfers = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(4);
    private final AtomicLong nonce = new AtomicLong(0);
    private volatile ValidatorSet currentValidators;

    public static class TransferState {
        volatile byte[] proofData;
        volatile CompletableFuture<byte[]> attestationFuture;
        final String transferId;
        final long amount;
        final String recipient;
        volatile boolean finalized;
        volatile CallbackHandle callbackRef;

        TransferState(String transferId, long amount, String recipient) {
            this.transferId = transferId;
            this.amount = amount;
            this.recipient = recipient;
            this.finalized = false;
        }
    }

    public static class CallbackHandle {
        private TransferState stateRef;
        private final long createdAt;
        private volatile boolean invalidated;

        CallbackHandle(TransferState state) {
            this.stateRef = state;
            this.createdAt = System.nanoTime();
            this.invalidated = false;
        }

        public TransferState getState() {
            return stateRef;
        }

        public void clearReference() {
            this.stateRef = null;
            this.invalidated = true;
        }

        public boolean isValid() {
            return !invalidated;
        }
    }

    public static class ValidatorSet {
        private final Map<String, byte[]> validators;
        private final int quorum;

        ValidatorSet(Map<String, byte[]> validators, int quorum) {
            this.validators = new HashMap<>(validators);
            this.quorum = quorum;
        }

        public boolean hasQuorum(int attestations) {
            return attestations >= quorum;
        }
    }

    /**
     * Initiates a cross-chain transfer with async attestation gathering
     */
    public CompletableFuture<String> initiateTransfer(String recipient, long amount, byte[] sourceProof) {
        String transferId = generateTransferId(recipient, amount);
        TransferState state = new TransferState(transferId, amount, recipient);
        state.proofData = sourceProof.clone();

        pendingTransfers.put(transferId, state);

        CallbackHandle handle = new CallbackHandle(state);
        state.callbackRef = handle;

        // Schedule attestation collection with timeout
        state.attestationFuture = collectAttestationsAsync(handle);

        // Schedule cleanup after timeout - this creates the dangling reference issue
        scheduler.schedule(() -> {
            timeoutTransfer(transferId, handle);
        }, 30, TimeUnit.SECONDS);

        return state.attestationFuture.thenApply(proof -> {
            finalizeTransfer(transferId, proof);
            return transferId;
        });
    }

    /**
     * Called when attestation timeout fires
     * BUG: handle.getState() may reference a TransferState that was
     * removed from pendingTransfers and re-added with same ID by a new transfer.
     * The callback still holds the OLD CallbackHandle whose stateRef was
     * reassigned during cancelAndRetry, pointing to recycled memory/object.
     */
    private void timeoutTransfer(String transferId, CallbackHandle handle) {
        // Check validity - but there's a TOCTOU race here
        if (!handle.isValid()) {
            return;
        }

        TransferState state = handle.getState();
        if (state != null && !state.finalized) {
            // This operates on potentially stale/recycled state
            // The state object may have been reused for a different transfer
            state.finalized = true;
            state.attestationFuture.completeExceptionally(
                new TimeoutException("Attestation timeout for " + transferId));
            pendingTransfers.remove(transferId);
        }
    }

    /**
     * Cancel and retry creates the dangerous condition:
     * 1. Removes old state from map
     * 2. Creates new state with same transferId
     * 3. Old CallbackHandle still references old state object
     * 4. But the old state's fields get mutated by the timeout callback
     *    which races with the new transfer's attestation flow
     */
    public CompletableFuture<String> cancelAndRetry(String transferId, byte[] newProof) {
        TransferState oldState = pendingTransfers.remove(transferId);
        if (oldState != null) {
            // We clear the callback but DON'T cancel the scheduled timeout
            // The old CallbackHandle.stateRef is set to null...
            oldState.callbackRef.clearReference();
            // ...but there's a race: timeout may have already read handle.isValid()
            // and is between the isValid check and getState() call
        }

        // Reuse the same transferId - creates aliasing problem
        TransferState newState = new TransferState(transferId, oldState != null ? oldState.amount : 0, oldState != null ? oldState.recipient : "");
        newState.proofData = newProof.clone();

        // The old timeout callback's handle still exists on the scheduler
        // If timing is right: old callback passes isValid(), then clearReference() runs,
        // then getState() returns null... BUT if the scheduler thread cached the
        // stateRef field before clearReference, it operates on the old state
        // whose attestationFuture may have been completed by the NEW flow

        CallbackHandle newHandle = new CallbackHandle(newState);
        newState.callbackRef = newHandle;
        pendingTransfers.put(transferId, newState);

        newState.attestationFuture = collectAttestationsAsync(newHandle);

        scheduler.schedule(() -> {
            timeoutTransfer(transferId, newHandle);
        }, 30, TimeUnit.SECONDS);

        return newState.attestationFuture.thenApply(proof -> {
            finalizeTransfer(transferId, proof);
            return transferId;
        });
    }

    private CompletableFuture<byte[]> collectAttestationsAsync(CallbackHandle handle) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                Thread.sleep(100); // Simulate network delay
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }

            // The handle might be dangling if cancelAndRetry was called
            TransferState state = handle.getState();
            if (state == null || state.finalized) {
                throw new CompletionException(new IllegalStateException("Transfer invalidated"));
            }

            return state.proofData;
        });
    }

    private void finalizeTransfer(String transferId, byte[] proof) {
        TransferState state = pendingTransfers.get(transferId);
        if (state != null) {
            state.finalized = true;
            // In production: emit event, update ledger state
        }
    }

    private String generateTransferId(String recipient, long amount) {
        return "tx_" + recipient.hashCode() + "_" + nonce.incrementAndGet();
    }

    /**
     * Health check endpoint for Kubernetes liveness probe
     */
    public boolean isHealthy() {
        return !scheduler.isShutdown() && pendingTransfers.size() < 10000;
    }

    public void shutdown() {
        scheduler.shutdownNow();
        pendingTransfers.clear();
    }
}
